  pp_file_req: 'My.gov.uz dan olingan pasport faylini biriktiring',
  nav_help: 'Yo‘riqnoma', help_eyebrow: 'Platformadan qanday foydalaniladi', tip_a: 'Bu qanday sahifa',
  help_more: 'To‘liq yo‘riqnoma', help_show: 'Qayerdaligini ko‘rsatish', help_tour: 'Tanishuv turi',
  help_hi: 'Besh daqiqa — va hammasi tushunarli', help_hi_s: 'Quyida har bir amal bo‘yicha qisqa yo‘riqnoma bor. Qadamlarni ochish uchun kartani bosing yoki tanishuv turini ishga tushiring: u kerakli tugmalarni ekranning o‘zida yoritib beradi.',
  help_hi_admin: 'Platforma boshqaruvi — bitta joyda', help_hi_admin_s: 'Quyida nima qayerda sozlanishi va qanday tartibda ekani yozilgan. Qadamlarni ochish uchun kartani bosing yoki admin-panel bo‘ylab turni ishga tushiring.',
  help_stuck_t: 'Agar biror narsa chiqmasa', help_stuck: 'AI-mentorga yozing — pastki o‘ng burchakdagi ko‘k tugma. U faqat kompaniya standartlari asosida javob beradi. Javob topilmasa, “Metodistga yuborish” tugmasini bosing: savol metodistga boradi, javobini bildirishnomalarda (qo‘ng‘iroqcha) olasiz.',
  help_stuck_admin: 'Ma’lumotlar faqat shu brauzerda saqlanadi: bu prototip. Sahifa pastidagi “Demo ma’lumotlarni tiklash” tugmasi hammasini boshlang‘ich holatga qaytaradi — xodimlar, jurnallar va daraja sozlamalari qayta yoziladi.',

  tour_eyebrow: 'Platforma bilan tanishuv', tour_skip: 'O‘tkazib yuborish', tour_next: 'Keyingisi', tour_done: 'Tayyor',
  tr_home_t: 'Bosh sahifa', tr_home: 'Kun shu yerdan boshlanadi: joriy dars, bugungi vazifalar va progress. “Davom ettirish” tugmasi doim siz to‘xtagan joyni ochadi.',
  tr_tree_t: 'Standartlar ro‘yxati', tr_tree: 'Chap tomonda — barcha bo‘limlar va darslar. Yopiq darslar oldingi dars imtihonidan keyin ochiladi; qulf belgisi — ruxsat hali berilmagan.',
  tr_tasks_t: 'Vazifalar', tr_tasks: 'Bu yerga aynan hozir bajarilishi kerak bo‘lgan ishlar tushadi: o‘zgargan standart bilan tanishish yoki xatodan keyin qayta o‘qish. Yonidagi raqam — nechta vazifa qolgani.',
  tr_cases_t: 'Keyslar', tr_cases: 'Kompaniya ishidan olingan haqiqiy holatlar. Vaziyatingizni o‘z so‘zlaringiz bilan yozing — keys-mentor o‘xshash holatni topib, o‘shanda nima qilinganini aytadi.',
  tr_base_t: 'Baza', tr_base: 'Kompaniya jurnallari va atamalar lug‘ati. Bu yerda faqat metodist shaxsan sizga ochgan narsalar ko‘rinadi; ba’zi jurnallarga yozuv qo‘shish va blankalarni yuklab olish mumkin.',
  tr_path_t: 'Mening yo‘lim', tr_path: 'Sizning darajangiz, XP va keyingi bosqich talablari. Daraja ustiga sichqonchani olib boring — nima o‘sishi kerakligi va kompaniya nima berishi ko‘rinadi.',
  tr_ai_t: 'AI-mentor', tr_ai: 'Pastki o‘ng burchakdagi tugma. Standartlar haqida o‘z so‘zlaringiz bilan so‘rang — javob faqat kompaniya hujjatlari asosida, manbasi ko‘rsatilgan holda beriladi.',
  tr_help_t: 'Yo‘riqnoma doim yoningizda', tr_help: 'Sahifa sarlavhasi yonidagi “?” belgisi shu sahifada nima qilinishini tushuntiradi. To‘liq yo‘riqnoma — ismingiz ostidagi menyuda, o‘sha yerdan bu turni qayta ishga tushirish ham mumkin.',
  tr_inbox_t: 'So‘rovlar', tr_inbox: 'Xodimlarning savollari, imtihonga, ruxsatga va darajani oshirishga so‘rovlar. O‘qilmaganlari nuqta bilan belgilanadi, menyudagi raqam — nechta so‘rov ochiq.',
  tr_monitor_t: 'Monitoring', tr_monitor: 'Kim qanday ilgarilayapti: o‘tilgan darslar, o‘rtacha ball, kunlik daqiqalar, kim orqada qolyapti. Bu yerdan kimga yordam kerakligi ko‘rinadi.',
  tr_quality_t: 'Sifat', tr_quality: 'Uchta bo‘lim: xatolar jurnali (tizim o‘zi qayta o‘qishni tayinlaydi), baholari bilan AI-trenajyor va o‘zgargan standartlar bilan tanishish.',
  tr_cms_t: 'Kontent', tr_cms: 'To‘rt bo‘lim: darslar, keyslar, jurnallar va terminologiya. Shu yerda kim nimani ko‘rishi va kim yozuv qo‘sha olishi ham sozlanadi.',
  tr_staff_t: 'Xodimlar', tr_staff: 'Xodim qo‘shish, login berish, status va darajani o‘zgartirish. Xodimlar darajalar bo‘yicha guruhlangan, “So‘rovnoma” ustuni esa kayfiyat va muammoli mavzularni ko‘rsatadi.',
  tr_levels_t: 'Darajalar', tr_levels: 'Karyera zinapoyasi: XP chegarasi, majburiy bo‘limlar, minimal ball va har bir bosqich talablari. Nomlar va tavsiflar — to‘rtala tilda.',

  hp_first_t: 'Birinchi kirish', hp_first_s: 'Birinchi kuni nima qilinadi',
